            }

            @Override
            public float matchCost() {
              return 0;
            }

            @Override
            public int docID() {
              return NO_MORE_DOCS;
            }

            @Override
            public int nextDoc() {
              return NO_MORE_DOCS;
            }

            @Override
            public int advance(int target) {
              return NO_MORE_DOCS;
            }

            @Override
            public long cost() {
              return 0;
            }
          };
        }

        @Override
        public IntervalMatchesIterator matches(String field, LeafReaderContext ctx, int doc) {
          return null;
        }

        @Override
